def jet_spec(name):
    original=name
    if name.startswith('grad_theta_'):
        name='theta_d'+name.rsplit('_',1)[1]
    match=re.fullmatch(r'(u_[123]|theta|e_W)((?:_t{1,2})?(?:_?d[123])*)', name)
    if not match:
        return None
    channel,suffix=match.groups()
    return {'name':original,'channel':channel,'timeOrder':2 if '_tt' in suffix else 1 if '_t' in suffix else 0,
            'spatialOrders':[len(re.findall('d'+str(i),suffix)) for i in (1,2,3)]}

def quotient_recurrence(numerator, denominator, grades, cancel):
    """Exact multivariate quotient recurrence; no full coefficient-domain Poly."""
    result={}
    for a,b in sorted(grades,key=lambda g:(sum(g),g)):
        remainder=numerator.get((a,b),0)
        for (i,j),value in denominator.items():
            if (i or j) and i<=a and j<=b:
                remainder-=value*result.get((a-i,b-j),0)
        result[a,b]=cancel(remainder/denominator[(0,0)])
    return result

def bind(value):
        syms=value.atoms(sp.Symbol);named={s.name:s for s in syms}
        require(len(named)==len(syms),'no ambiguous raw symbol assumptions')
        dm={s:context['densityMap'][s.name] for s in syms if s.name in context['densityMap']}
        value=value.xreplace(dm)
        for _ in range(len(context['profileEqualities'])+2):
            mapping={s:context['profileEqualities'][s.name] for s in value.atoms(sp.Symbol)
                     if s.name in context['profileEqualities']}
            changed=value.xreplace(mapping)
            if changed==value:break
            value=changed
        else:raise ValueError('background substitution cycle')
        mapping={s:context['numeric'][s.name] for s in value.atoms(sp.Symbol) if s.name in context['numeric']}
        require(not any(s in mapping for s in (eta,sigma,eps)),'independent grades/epsilon')
        return value.xreplace(mapping)

def profile(expr):
        mapping={}
        for s in expr.free_symbols:
            hit=re.fullmatch(r'([wm])1_profile((?:_?d[123])*)',s.name)
            if hit:
                base,suffix=hit.groups();directions=re.findall('d([123])',suffix)
                mapping[s]=sp.S.Zero if any(d!='1' for d in directions) else profile_length**len(directions)*sp.diff(w if base=='w' else m,x,len(directions))
        result=sp.cancel(expr.xreplace(mapping))
        J.emit('profile-map-'+str(len(J.artifacts)),{'original':expr,'map':[[a,b] for a,b in mapping.items()],
            'oneDimensional':result,'L':profile_length,'independentSigma':True,'profileTransformEvaluated':False})
        require(result.free_symbols<={x},'coefficient field fully bound')
        return result

def wave_jet(atom, point=X, sector=None):
    """The trial-field ansatz, with every spatial and temporal jet mapped.

    Solenoidal trials are curls; longitudinal trials are gradients.  This is
    the compact-support weak-restriction convention, without a Fourier projector.
    """
    name = str(atom)
    if name.startswith('grad_theta_'):
        name = 'theta_d' + name.rsplit('_', 1)[1]
    match = re.fullmatch(r'(u_[123]|theta|e_W)((?:_t{1,2})?(?:_?d[123])*)', name)
    if not match:
        raise ValueError(('wave jet', name))
    base, suffix = match.groups()
    if sector == 'TRANSVERSE' and base.startswith('u_'):
        i = int(base[-1]) - 1
        j, k = (i + 1) % 3, (i + 2) % 3
        potentials = [field(f's11cc2TrialA{n}', point, (2, 0, 0)) for n in range(3)]
        value = sp.diff(potentials[k], point[j]) - sp.diff(potentials[j], point[k])
    elif sector == 'LONGITUDINAL' and base.startswith('u_'):
        value = sp.diff(field('s11cc2TrialPhi', point, (2, 0, 0)), point[int(base[-1])-1])
    elif sector == 'THETA' and base == 'theta':
        value = field('s11cc2TrialTheta', point, (0, 0, 0))
    elif sector == 'E_W' and base == 'e_W':
        value = field('s11cc2TrialE', point, (0, 0, 0))
    elif sector is not None:
        value = sp.S.Zero
    else:
        value = field('s11cc2Field' + base, point, (1, 0, 0) if base.startswith('u_') else (0, 0, 0))
    for direction in re.findall(r'd([123])', suffix):
        value = sp.diff(value, point[int(direction)-1])
    if '_tt' in suffix:
        value = sp.diff(value, TIME, 2)
    elif '_t' in suffix:
        value = sp.diff(value, TIME)
    return value

def at_source(self, expression):
        """Translate the full source to its integration point, including density.

        Background jets are independent supplied coefficient fields here.  No
        field is replaced by its constant representative during translation.
        """
        replacements = {}
        for a in expression.atoms(sp.Symbol):
            if a in self.wave:
                replacements[a] = wave_jet(a, Y)
            elif re.match(r'(?:W_bg|mu_R_bg|[wm]1_profile)(?:$|_d)', a.name):
                base=a.name.split('_d')[0]
                name=re.sub(r'_([a-zA-Z0-9])',lambda m:m[1].upper(),'s11cc2Coefficient'+base)
                function=sp.Function(name)
                NEW_DIMENSIONS[function]=tuple(DIMENSION_SCHEMA[base])
                indices=[int(n)-1 for n in re.findall(r'd([123])',a.name)]
                value=sp.diff(function(*Y),*(Y[i] for i in indices)) if indices else function(*Y)
                if base in ('w1_profile','m1_profile'):
                    value*=self.values['L_W']**len(indices)
                replacements[a]=value
        return expression.xreplace(replacements)
